{
    audio: 2,
    trigger: { player: "phaseJieshuBegin" },
    filter(event, player) {
      return player.getExpansions("qixing").length;
    },
    async cost(event, trigger, player) {
      const {
        bool,
        targets,
        links: cost_data
      } = await player.chooseButtonTarget({
        createDialog: [get.prompt2(event.skill), player.getExpansions("qixing")],
        selectButton: 1,
